import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;

/// PLACEHOLDER options. Real values are generated by `flutterfire configure`,
/// which overwrites this file — see ../../docs/FIREBASE_SETUP.md.
///
/// While the apiKey still contains "REPLACE", the app runs in OFFLINE mode on
/// sample data (no Firebase calls are made). Once real values are in place the
/// app switches to Firebase Auth + Firestore automatically.
class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform => const FirebaseOptions(
        apiKey: 'REPLACE_WITH_FLUTTERFIRE',
        appId: 'REPLACE_WITH_FLUTTERFIRE',
        messagingSenderId: 'REPLACE_WITH_FLUTTERFIRE',
        projectId: 'REPLACE_WITH_FLUTTERFIRE',
        storageBucket: 'REPLACE_WITH_FLUTTERFIRE',
      );
}
